/* Golden do jogo anterior ao P1C.2: funções skill() e castOn() congeladas.
 * Nunca alterar este arquivo sem justificar mudança intencional no comportamento.
 */
function skill(which){if(!canPlay())return;stopAuto();const p=G.hero,c=CLASSES[p.classId],s=c.skills[which];if(p.mana<s.cost){log(`Foco insuficiente. Precisa de ${s.cost} pontos.`,'✧');beep(125);return;}if(s.target){aim=aim===which?null:which;updateAim();if(aim!==null){toast(`Selecione um alvo para ${s.name}`);beep(505);}}else{aim=null;updateAim();p.mana-=s.cost;if(p.classId==='vigia'){p.hp=clamp(p.hp+7+p.level,0,p.maxhp);p.buff=4;log('Bastião: você recupera vida e ergue uma guarda rúnica.','◆');}else{let hit=0;for(const e of [...G.enemies])if(dist(p,e)<=2){heroHit(e,6+p.level,'Espinhos','skill');if(e.hp>0){e.root=2;hit++;}}relicEvent('onRoot',{count:hit});if(hit&&hasTalent('e_drenante'))p.mana=clamp(p.mana+Math.min(2,hit),0,p.maxmana);log(hit?`${hit} inimigos enredados nas raízes de Ironwood.`:'Espinhos crescem, mas não alcançam ninguém.','❋');}beep(480,.14);worldTurn();updateHUD();save();}}
function castOn(x,y){if(!canPlay()||aim===null)return;const p=G.hero,c=CLASSES[p.classId],s=c.skills[aim];if(dist(p,{x,y})>s.range||!isVisible(x,y)||!lineClear(p.x,p.y,x,y)){log('A magia não consegue alcançar esse ponto.','✧');beep(125);return;}const e=enemyAt(x,y);if(!(p.classId==='arcanista'&&aim===1)&&!e){log('Toque em um inimigo para usar essa habilidade.','✧');return;}if(p.mana<s.cost){aim=null;updateAim();return;}p.mana-=s.cost;
  if(p.classId==='vigia'){const dmg=p.atk+rand(6,10)+p.level;heroHit(e,dmg,'Martelo rúnico','skill');if(e.hp>0)e.stun=2;if(hasTalent('v_runa'))for(const other of [...G.enemies])if(other!==e&&other.hp>0&&dist(other,e)<=1)heroHit(other,Math.max(1,Math.floor(dmg/2)),'Estilhaço rúnico','skill');}
  else if(p.classId==='arcanista'&&aim===0){const dmg=11+rand(0,5)+p.level*2;heroHit(e,dmg,'Glifo de luz 光','skill');if(e.hp<=0&&hasTalent('a_faminto'))p.mana=clamp(p.mana+3,0,p.maxmana);if(hasTalent('a_ricochete')){const second=G.enemies.find(v=>v!==e&&v.hp>0&&dist(v,e)<=2&&isVisible(v.x,v.y)&&lineClear(p.x,p.y,v.x,v.y));if(second)heroHit(second,Math.max(1,Math.floor(dmg/2)),'Eco de luz 光','skill');}}
  else if(p.classId==='arcanista'){let hit=0;for(const victim of [...G.enemies])if(Math.hypot(victim.x-x,victim.y-y)<=1.6){heroHit(victim,7+rand(1,4)+p.level,'Sonho 夢','skill');if(victim.hp>0)victim.stun=hasTalent('a_sonho')?3:2;hit++;}if(!hit)log('O sonho se desfaz na pedra sem encontrar uma mente.','夢');}
  else if(p.classId==='errante'){const rangeBonus=hasTalent('e_tiro')?Math.min(8,Math.max(0,dist(p,e)-2)*2):0;heroHit(e,13+rand(0,6)+p.level*2+rangeBonus,'Tiro fantasma','skill');}
  aim=null;updateAim();beep(730,.17,'triangle');worldTurn();updateHUD();save();}
